let width=570,height=450,angle=.42,frame=0,last=0,paintAt=0,speed=1,targetSpeed=1,visible=true,resizeObserver,intersectionObserver,media;
function project(p){const c=Math.cos(angle),s=Math.sin(angle),tilt=-.18;const x=p.x*c+p.z*s,z0=-p.x*s+p.z*c,y=p.y*Math.cos(tilt)-z0*Math.sin(tilt),z=p.y*Math.sin(tilt)+z0*Math.cos(tilt),perspective=3.5/(3.5-z*.55),radius=Math.min(width,height)*.395;return {x:width/2+x*radius*perspective,y:height/2+y*radius*perspective,scale:(.56+(z+1)*.25)*perspective,opacity:.12+(z+1)*.43,z:Math.round((z+1)*100)};}
function initial(p){const v=project(p);return {transform:`translate3d(${v.x}px,${v.y}px,0) translate(-50%,-50%) scale(${v.scale})`,opacity:v.opacity,zIndex:v.z};}
function draw(){points.forEach((p,i)=>{const el=nodes[i];if(!el)return;const v=project(p);el.style.transform=`translate3d(${v.x}px,${v.y}px,0) translate(-50%,-50%) scale(${v.scale})`;el.style.opacity=v.opacity;el.style.zIndex=v.z;});}
function running(){return !paused.value&&visible&&!document.hidden;}
function tick(time){if(!running()){frame=0;last=0;return;}const dt=last?Math.min(time-last,50):16;last=time;speed+=(targetSpeed-speed)*.055;angle+=dt*Math.PI*2/70000*speed;if(time-paintAt>28){draw();paintAt=time;}frame=requestAnimationFrame(tick);}
function schedule(){if(running()&&!frame){last=0;frame=requestAnimationFrame(tick);}else if(!running()&&frame){cancelAnimationFrame(frame);frame=0;last=0;}}
function toggle(){paused.value=!paused.value;schedule();}
function slow(){targetSpeed=.12;}
function normal(){targetSpeed=1;activeName.value='';}
function reduced(event){if(event.matches){paused.value=true;schedule();}}
onMounted(()=>{media=matchMedia('(prefers-reduced-motion: reduce)');paused.value=media.matches;media.addEventListener('change',reduced);resizeObserver=new ResizeObserver(entries=>{const rect=entries[0].contentRect;width=rect.width;height=rect.height;draw();});resizeObserver.observe(stage.value);intersectionObserver=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;schedule();},{threshold:.03});intersectionObserver.observe(stage.value);document.addEventListener('visibilitychange',schedule);draw();schedule();});
